const data = $input.item.json;
const symbol = data.meta.symbol;
let values = data.values;

values = values.slice().reverse();
const closes = values.map(v => parseFloat(v.close));
const n = closes.length;

const periodReturn = (closes[n - 1] - closes[0]) / closes[0];

const dailyReturns = [];
for (let i = 1; i < n; i++) {
  dailyReturns.push((closes[i] - closes[i - 1]) / closes[i - 1]);
}
const mean = dailyReturns.reduce((a, b) => a + b, 0) / dailyReturns.length;
const variance = dailyReturns.reduce((a, b) => a + (b - mean) ** 2, 0) / dailyReturns.length;
const annualisedVol = Math.sqrt(variance) * Math.sqrt(252);

// 50/200-day SMA — falls back gracefully if fewer than 200 days are available
const sma = (window) => {
  const w = Math.min(window, n);
  return closes.slice(-w).reduce((a, b) => a + b, 0) / w;
};
const sma50 = sma(50);
const sma200 = sma(200);
const priceVsSma50 = (closes[n - 1] - sma50) / sma50;
const priceVsSma200 = (closes[n - 1] - sma200) / sma200;
const goldenCross = sma50 > sma200; // 50-day above 200-day = bullish signal

let peak = closes[0];
let maxDd = 0;
for (const price of closes) {
  if (price > peak) peak = price;
  const dd = (price - peak) / peak;
  if (dd < maxDd) maxDd = dd;
}

const result = {
  symbol,
  period_days: n,
  period_return_pct: Math.round(periodReturn * 10000) / 100,
  annualised_volatility_pct: Math.round(annualisedVol * 10000) / 100,
  price_vs_sma50_pct: Math.round(priceVsSma50 * 10000) / 100,
  price_vs_sma200_pct: Math.round(priceVsSma200 * 10000) / 100,
  golden_cross: goldenCross,
  max_drawdown_pct: Math.round(maxDd * 10000) / 100,
};

return { json: result };

const items = $input.all(); const date = new Date().toISOString().split('T')[0]; let report = `# Quant Desk Report — ${date}

`; for (const item of items) { const raw = item.json.output; let d; try { d = JSON.parse(raw); } catch (e) { const match = raw.match(/\{[\s\S]*\}/); d = match ? JSON.parse(match[0]) : {}; } report += `## ${d.symbol}
`; report += `- **Position size:** $${d.position_size_usd}
`; report += `- **Stop distance:** ${d.stop_distance_pct}%
`; report += `- **Rejected:** ${d.rejected}
`; report += `- **Reasoning:** ${d.reason}

`; } return [{ json: { report_markdown: report, date } }];
